function loadFinancialClose(d){var key='daily_'+d;if(financialCloseLoading[key]||Object.prototype.hasOwnProperty.call(financialCloseState,key))return;financialCloseLoading[key]=true;A().runFinancialClose({action:'get',closeType:'DAILY_CLOSE',businessDate:d}).then(function(r){var x=(r&&r.data)||r||{};financialCloseState[key]=x.current||null;}).catch(function(){financialCloseState[key]=null;}).finally(function(){financialCloseLoading[key]=false;if(isTab('dailyreport'))renderDailyReport();});}
function wireFinancialClose(d){var a=A(),run=document.getElementById('drRunClose'),cert=document.getElementById('drCertifyClose');if(run)run.onclick=function(){financialCloseLoading['daily_'+d]=true;renderDailyReport();a.runFinancialClose({closeType:'DAILY_CLOSE',businessDate:d}).then(function(r){var x=(r&&r.data)||r||{};financialCloseState['daily_'+d]=x;alert(x.status==='EXCEPTIONS_OPEN'?'Close completed with '+(x.exceptions||[]).length+' exception(s). Certification remains blocked.':'Daily close reconciled. Review timing items, then certify.');}).catch(function(e){alert('Could not run close: '+((e&&e.message)||e));}).finally(function(){financialCloseLoading['daily_'+d]=false;renderDailyReport();});};if(cert)cert.onclick=function(){var row=financialCloseState['daily_'+d];window.AccazaFormDialog.run({title:'Certify Daily Financial Close',subtitle:d+' · revision '+row.revision+'. Certification locks this snapshot; later Finance activity reopens it for a new revision.',submitLabel:'Approve & certify',busyLabel:'Certifying…',fields:[{name:'reason',label:'Certification note',type:'textarea',required:true,maxLength:500},{name:'confirmed',label:'I reviewed the Admin, Finance, cash custody, inventory, AP/AR and timing-item controls',type:'checkbox',required:true}]},function(v){return a.managerApproval('certify_financial_close','daily_'+d,null,v.reason).then(function(ap){return a.runFinancialClose({action:'certify',closeType:'DAILY_CLOSE',businessDate:d,reason:v.reason,approvalId:ap.approvalId});});}).then(function(r){var x=(r&&r.data)||r||{};financialCloseState['daily_'+d]=Object.assign({},row,{status:'CERTIFIED',certification:x.certification});alert('Daily close certified.');renderDailyReport();}).catch(function(){});};document.querySelectorAll('[data-dr-shift-close]').forEach(function(button){button.onclick=function(){var id=this.getAttribute('data-dr-shift-close');if(!id)return;var b=this;b.disabled=true;b.textContent='Reconciling…';a.runFinancialClose({closeType:'SHIFT_CLOSE',businessDate:d,shiftId:id}).then(function(r){var x=(r&&r.data)||r||{};alert('Shift close '+closeStatusLabel(x.status)+' · '+(x.exceptions||[]).length+' exception(s).');}).catch(function(e){alert('Could not run shift close: '+((e&&e.message)||e));}).finally(function(){b.disabled=false;b.textContent='Run shift reconciliation';});};});}
// Channel of a sale for the Daily Report. Platform tags win; POS-keyed = in-store; anything else (website orders, no shiftId) = online.
