      if(c==='instore'||c==='online'){ch.gross+=s.gross;ch.disc+=s.discount;ch.net+=s.net;nt=s.net;netTot+=s.net;}
      else{var g=s.gross;nt=s.net;ch.gross+=g;ch.disc+=s.discount;ch.comm+=Number(o.commission)||0;ch.net+=nt;netTot+=nt;}
      ch.refund+=s.refund;
      refundsTot+=s.refund;
