      if(o.shiftId){var g2=byShift[o.shiftId]||(byShift[o.shiftId]={tx:0,net:0,cash:0,nonCash:0,cashTx:0});g2.tx++;g2.net+=nt;var hasCash=false;pays.forEach(function(p){var amount=Number(p.amount)||0;if(p.method==='Cash'){g2.cash+=amount;hasCash=true;}else g2.nonCash+=amount;});if(hasCash)g2.cashTx++;}
      var lineItems=o.correctedLineItems||o.lineItems||[],lineSales=0;lineItems.forEach(function(li){var qty=Number(li.qty)||0,unitTotal=Number(li.unitTotal)||0;lineSales+=qty*unitTotal;var k=li.itemKey||li.name||'?';if(!itemsM[k])itemsM[k]={name:li.name||k,qty:0,sales:0};itemsM[k].qty+=qty;itemsM[k].sales+=qty*unitTotal;});
      var occurredAt=drTransactionTimestamp(o,s.ts);txns.push({occurredAt:occurredAt,dateKey:drTransactionDateKey(occurredAt,o.date),dateLabel:drTransactionDateLabel(occurredAt,o.date),timeLabel:drTransactionTimeLabel(occurredAt,o.time),dateTime:drTransactionDateTime(occurredAt,o.date,o.time),id:o.id,shiftId:o.shiftId||'',channel:chan[c].lbl,method:pays.map(function(p){return p.method;}).join('+'),amount:Number(o.total)||0,refund:s.refund});
      reconRows.push({id:o.id,dateTime:drTransactionDateTime(occurredAt,o.date,o.time),net:nt,gross:s.gross,discount:s.discount,refund:s.refund,paymentAmount:pays.reduce(function(sum,p){return sum+(Number(p.amount)||0);},0),paymentKnown:!!paymentRows||o.total!=null||o.payment!=null,lineSales:lineSales,hasLines:lineItems.length>0});
