    // shifts whose trading day == d, with per-shift rollup
    var shiftRows=Object.keys(sh).map(function(k){return Object.assign({id:k},sh[k]);}).filter(function(s){return shiftDay[s.id]===d;}).sort(function(a,b){return (a.openAt||0)-(b.openAt||0);}).map(function(s){var g=byShift[s.id]||{tx:0,net:0,cash:0,nonCash:0,cashTx:0},open=s.status!=='closed',cash=drShiftCash(s,g);return {id:s.id,shiftReference:s.shiftReference||'',staff:s.staff||'',openAt:s.openAt,closeAt:s.closeAt||null,open:open,tx:g.tx,net:g.net,nonCash:g.nonCash,cashTx:g.cashTx,cashControl:cash};});
