    var channelMixRows=['instore','grabfood','foodpanda','online'].map(function(c){var x=chan[c];return '<tr><td>'+x.lbl+'</td><td class="r">'+x.tx+'</td><td class="r">'+peso(x.net)+'</td></tr>';}).join('');
    var platformRows=['grabfood','foodpanda'].map(function(c){var x=chan[c];if(!x.comm)return '';return '<tr><td>'+x.lbl+'</td><td class="r">'+peso(x.comm)+'</td></tr>';}).join('');
    var platformFeesHtml='<div class="az-sec">Platform fees (expense only)</div><div class="pz-card dr-detail-card" id="drPlatformFees" style="margin-bottom:.7rem;"><div class="az-note" style="margin-bottom:.55rem;"><b>Important:</b> commission is a selling expense. It is not deducted from revenue sales and never changes the channel net-sales figure.</div><table class="pz-tbl"><thead><tr><th>Platform</th><th class="r">Commission expense</th></tr></thead><tbody>'+(platformRows||'<tr><td colspan="2" style="color:var(--tl);">No platform commissions recorded.</td></tr>')+'<tr class="tot"><td>Total platform fees</td><td class="r">−'+peso(channelCommissionTotal)+'</td></tr></tbody></table></div>';
