    var itemRows=items.map(function(x){return '<tr><td>'+esc(x.name)+'</td><td class="r">'+drNum(x.qty)+'</td><td class="r">'+peso(x.sales)+'</td></tr>';}).join('')||'<tr><td colspan="3" style="color:var(--tl);">No sales this day.</td></tr>';
    var txnRows=txns.map(function(t){var rollover=t.dateKey&&t.dateKey!==d;return '<tr><td><span style="display:inline-block;border-radius:999px;padding:.13rem .42rem;font-weight:700;background:'+(rollover?'#fff0cf;color:#7a4b00':'#e7f1ff;color:#174f88')+';">'+esc(t.dateLabel)+'</span><span style="margin-left:.38rem;white-space:nowrap;">'+esc(t.timeLabel)+'</span><small style="display:block;margin-top:.16rem;color:'+(rollover?'#9a5d00':'var(--tl)')+';">'+(rollover?'After midnight · same trading shift':'Trading-date transaction')+'</small></td><td>'+esc(t.id)+'</td><td>'+esc(t.channel)+'</td><td>'+esc(t.method)+'</td><td class="r">'+peso(t.amount)+(t.refund?(' · R '+peso(t.refund)):'')+'</td></tr>';}).join('')||'<tr><td colspan="5" style="color:var(--tl);">No sales this day.</td></tr>';
