    var bridgeRows='<tr><td>Payment tender before refunds</td><td class="r">'+peso(reconciliation.tenderBeforeRefunds)+'</td><td>Less: refunds '+peso(reconciliation.refunds)+'</td><td>Net tender '+peso(reconciliation.netTender)+'</td></tr>'
