    var reconciliationHtml='<div class="az-sec">Sales Control</div><section class="pz-card dr-detail-card" id="drReconciliation" style="margin-bottom:.7rem;"><div class="az-note" style="margin-bottom:.65rem;"><b>Board view:</b> Revenue sales is the sales figure. Tender and item detail are supporting controls; any difference is shown as a signed variance. '+reconciliation.sales+' qualifying sale(s).</div><div style="overflow-x:auto;margin-bottom:.7rem;"><table class="pz-tbl"><thead><tr><th>Channel mix</th><th class="r">Transactions</th><th class="r">Revenue sales</th></tr></thead><tbody>'+channelMixRows+'<tr class="tot"><td>Total</td><td class="r">'+channelTxTotal+'</td><td class="r">'+peso(netTot)+'</td></tr></tbody></table></div><div style="overflow-x:auto;"><table class="pz-tbl"><thead><tr><th>Control</th><th class="r">Amount</th><th>Status</th><th>What it means</th></tr></thead><tbody>'+reconRows+'</tbody></table></div><details style="margin-top:.65rem;"><summary><b>Show calculation and exceptions</b></summary><div style="overflow:auto;margin-top:.55rem;"><table class="pz-tbl"><thead><tr><th>Bridge step</th><th class="r">Amount</th><th>Adjustment</th><th>Result / note</th></tr></thead><tbody>'+bridgeRows+'</tbody></table></div>'+(reconIssueRows?'<div style="overflow:auto;margin-top:.55rem;"><table class="pz-tbl"><thead><tr><th>Reason</th><th>Order</th><th>Date &amp; time</th><th class="r">Variance</th></tr></thead><tbody>'+reconIssueRows+'</tbody></table></div>':'<div class="az-note" style="margin-top:.55rem;color:#176b3a;"><b>No order-level exceptions above ₱0.01.</b></div>')+'</details></section>';
