    var shiftCards=shiftRows.map(function(s){var c=s.cashControl||{},status=s.open?'OPEN — close shift first':'CLOSED — ready to reconcile',tone=s.open?'#fff9e8':(c.variance!=null&&Math.abs(c.variance)>=.005?'#fff0ef':'#eaf7ee'),openClose=(s.openAt?drTransactionDateTime(s.openAt,'',''):'—')+(s.closeAt?(' → '+drTransactionDateTime(s.closeAt,'','')):(s.open?' → still open':''));return '<article class="pz-card" style="margin-bottom:.7rem;background:'+tone+';border:1px solid #d7c8b2;"><div style="display:flex;justify-content:space-between;gap:.7rem;align-items:flex-start;flex-wrap:wrap;"><div><div class="pz-lbl">'+esc(s.shiftReference||s.id)+' · '+esc(s.staff||'Register')+'</div><div class="pz-h" style="font-size:1.05rem;">'+esc(status)+'</div><div class="pz-sub">'+esc(openClose)+' · '+s.tx+' transaction(s)</div></div><button class="pz-btn sec" data-dr-shift-close="'+esc(s.id)+'"'+(s.open?' disabled title="Close this shift in Register Operations first"':'')+'>'+ (s.open?'Close in Register Operations':'Run shift reconciliation')+'</button></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:.55rem;margin-top:.75rem;"><div><span class="pz-lbl">Cash sales</span><b>'+peso(c.cashSales)+'</b><small style="display:block;">'+s.cashTx+' cash tx</small></div><div><span class="pz-lbl">Non-cash sales</span><b>'+peso(s.nonCash)+'</b></div><div><span class="pz-lbl">Opening float</span><b>'+peso(c.opening)+'</b></div><div><span class="pz-lbl">Cash in</span><b>+'+peso(c.payIns)+'</b></div><div><span class="pz-lbl">Cash tips</span><b>+'+peso(c.tips)+'</b></div><div><span class="pz-lbl">Cash refunds</span><b>−'+peso(c.cashRefunds)+'</b></div><div><span class="pz-lbl">Cash out</span><b>−'+peso(c.payOuts)+'</b></div><div><span class="pz-lbl">Expected drawer</span><strong style="display:block;font-size:1.15rem;">'+peso(c.expected)+'</strong><small>Equation '+peso(c.calculated)+'</small></div><div><span class="pz-lbl">Counted drawer</span><strong style="display:block;font-size:1.15rem;">'+(c.counted==null?'Not counted':peso(c.counted))+'</strong></div><div><span class="pz-lbl">Shortage / overage</span><strong style="display:block;font-size:1.15rem;color:'+(c.variance!=null&&Math.abs(c.variance)>=.005?'#a12b2b':'#176b3a')+';">'+(c.variance==null?'Not finalized':peso(c.variance))+'</strong></div><div><span class="pz-lbl">Float retained</span><strong style="display:block;font-size:1.15rem;">'+(c.retained==null?'Not finalized':peso(c.retained))+'</strong></div><div><span class="pz-lbl">Cash to hand over</span><strong style="display:block;font-size:1.15rem;">'+(c.settle==null?'Not finalized':peso(c.settle))+'</strong></div></div></article>';}).join('')||'<div class="az-note">No shifts opened on this trading day.</div>';
    var onlineTx=txns.filter(function(t){return !t.shiftId;}),onlineNet=onlineTx.reduce(function(sum,t){return sum+(Number(t.amount)||0)-(Number(t.refund)||0);},0);
    var shiftLoadNotice=shiftLoadError?'<div class="az-note" style="margin-bottom:.7rem;color:#8a2b2b;background:#fff0ef;border:1px solid #e7b8b8;">Shift data could not load. Cash-by-shift totals may be incomplete; check the connection and reload the report.</div>':'';
    var shiftAccountability='<div class="az-sec">Shift Cash Accountability</div><section class="pz-card dr-detail-card" id="drShifts" style="margin-bottom:.7rem;"><div class="az-note" style="margin-bottom:.7rem;"><b>Expected drawer = opening float + cash sales + cash tips + cash in − cash refunds − cash out.</b> Cash to hand over is counted drawer cash less the retained float. Non-cash and online sales never increase drawer cash.</div>'+shiftLoadNotice+shiftCards+(onlineTx.length?'<div class="az-sec" style="margin-top:.9rem;">Online / no-shift sales</div><div class="az-note">'+onlineTx.length+' transaction(s) · net '+peso(onlineNet)+' · not assigned to a register drawer.</div>':'')+'</section>';
    var html='<div class="pz-h">📆 Daily Report</div>'
      +'<div style="display:flex;gap:0.5rem;align-items:end;flex-wrap:wrap;margin-bottom:0.4rem;"><div><span class="pz-lbl">Trading day</span><input class="pz-in" id="drDate" type="date" value="'+d+'"/></div><button class="pz-btn ok" id="drPrint" style="padding:0.4rem 0.9rem;">🖨 Print</button><button class="pz-btn sec" id="drExcel" style="padding:0.4rem 0.9rem;">⬇ Excel</button></div>'
      +'<div class="az-note" style="margin:0 0 0.7rem;">Trading day = the day a shift opened; a shift stays whole even if it runs past midnight. Online orders count on their own date.</div>'
      +'<section class="dr-summary" aria-labelledby="drSummaryTitle"><div class="dr-summary-head"><div><span>Close-of-day snapshot</span><h3 id="drSummaryTitle">Daily summary</h3></div><small>Choose an amount to view its detail</small></div><div class="dr-summary-grid">'
        +'<button class="dr-summary-item primary" data-dr-target="drChannels"><span>Revenue sales</span><strong>'+peso(netTot)+'</strong><small>All sales channels →</small></button>'
        +'<button class="dr-summary-item" data-dr-target="drTransactions"><span>Transactions</span><strong>'+sales.length+'</strong><small>View every order →</small></button>'
        +'<button class="dr-summary-item" data-dr-target="drMethods"><span>Cash tender</span><strong>'+peso(cashReceived)+'</strong><small>Before refunds →</small></button>'
        +'<button class="dr-summary-item" data-dr-target="drMethods"><span>Non-cash tender</span><strong>'+peso(nonCashReceived)+'</strong><small>Before refunds →</small></button>'
