      +platformFeesHtml
      +'<div class="az-sec">Tender collected by method</div><div class="pz-card dr-detail-card" id="drMethods" style="margin-bottom:0.7rem;"><table class="pz-tbl"><tbody>'+methodRows+'<tr class="tot"><td>Tender before refunds</td><td class="r">'+peso(paymentTotal)+'</td></tr><tr><td>Less: refunds</td><td class="r">−'+peso(reconciliation.refunds)+'</td></tr><tr class="tot"><td>Tender collected after refunds</td><td class="r">'+peso(reconciliation.netTender)+'</td></tr></tbody></table><div class="az-note">Tender is cash custody evidence, not a second sales total. The Sales Control card shows its variance to revenue sales.</div></div>'
