  var sf=[['Shift','Cashier','Open','Close','Status','Transactions','Net sales','Cash transactions','Cash sales','Non-cash sales','Opening float','Cash in','Cash tips','Cash refunds','Cash out','Expected drawer','Counted drawer','Shortage / overage','Float retained','Cash to hand over']];(X.shiftRows||[]).forEach(function(s){var c=s.cashControl||{};sf.push([s.shiftReference||s.id,s.staff,s.openAt?new Date(s.openAt).toLocaleString('en-PH'):'',s.closeAt?new Date(s.closeAt).toLocaleString('en-PH'):'',s.open?'open':'closed',s.tx,s.net,s.cashTx,c.cashSales,s.nonCash,c.opening,c.payIns,c.tips,c.cashRefunds,c.payOuts,c.expected,c.counted==null?'':c.counted,c.variance==null?'':c.variance,c.retained==null?'':c.retained,c.settle==null?'':c.settle]);});
  ch.push(['TOTAL',ch.slice(1).reduce(function(s,r){return s+(Number(r[1])||0);},0),ch.slice(1).reduce(function(s,r){return s+(Number(r[2])||0);},0),ch.slice(1).reduce(function(s,r){return s+(Number(r[3])||0);},0),ch.slice(1).reduce(function(s,r){return s+(Number(r[4])||0);},0),X.netTot]);pf.push(['TOTAL',pf.slice(1).reduce(function(s,r){return s+(Number(r[1])||0);},0)]);
  me.push(['TOTAL',Object.keys(X.byMethod).reduce(function(s,k){return s+(Number(X.byMethod[k])||0);},0)]);it.push(['TOTAL',X.items.reduce(function(s,x){return s+(Number(x.qty)||0);},0),X.items.reduce(function(s,x){return s+(Number(x.sales)||0);},0)]);tx.push(['TOTAL','','','',X.txns.reduce(function(s,x){return s+(Number(x.amount)||0);},0),X.refundsTot]);ex.push(['TOTAL','',X.payoutTot+X.refundsTot]);
