  var wb=XLSX.utils.book_new();[['Shifts',sf],['Reconciliation',re],['Channels',ch],['Platform Fees',pf],['Methods',me],['Items',it],['Transactions',tx],['Expenses',ex]].forEach(function(p){XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(p[1]),p[0]);});XLSX.writeFile(wb,'daily-report-'+d+'.xlsx');
